mapper.select:
SELECT rps.id AS snapshotId, rps.room_category_id AS roomCategoryId, rps.channel_id AS channelId, rps.price_type AS priceType, CONCAT('PL', rps.id) AS logId, rc.name AS roomCategoryName, DATE_FORMAT(rps.biz_date, '%Y-%m-%d') AS priceDate, ca.channel_name AS channelName, rps.price_cent AS channelSalePrice, DATE_FORMAT(rps.updated_at, '%Y-%m-%d %H:%i:%s') AS operationTime, ( SELECT prev.price_cent FROM room_price_snapshot prev WHERE prev.camp_id = rps.camp_id AND prev.poi_id = rps.poi_id AND prev.room_category_id = rps.room_category_id AND prev.price_type = rps.price_type AND prev.channel_id = rps.channel_id AND prev.biz_date < rps.biz_date ORDER BY prev.biz_date DESC, prev.updated_at DESC, prev.id DESC LIMIT 1 ) AS previousPriceCent FROM room_price_snapshot rps JOIN room_category rc ON rc.room_category_id = rps.room_category_id AND rc.camp_id = rps.camp_id AND rc.status = 1 AND rc.is_deleted = 0 LEFT JOIN ( SELECT camp_id, channel_id, MIN(channel_name) AS channel_name FROM channel_account WHERE status = 'authorized' GROUP BY camp_id, channel_id ) ca ON ca.camp_id = rps.camp_id AND ca.channel_id = rps.channel_id WHERE rps.camp_id = #{campId} AND rps.status = 'active'
AND ( rc.name LIKE CONCAT('%', #{keyword}, '%') OR CAST(rps.id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR rps.price_type LIKE CONCAT('%', #{keyword}, '%') OR ca.channel_name LIKE CONCAT('%', #{keyword}, '%') )
AND rps.channel_id = #{channelId}
AND rps.biz_date >= #{adjustmentStart}
AND rps.biz_date <= #{adjustmentEnd}
AND rps.updated_at >= #{operationStart}
AND rps.updated_at < #{operationEndExclusive}
ORDER BY rps.updated_at DESC, rps.id DESC
